/* GENERATED by scripts/build-atlas-data.cjs from atlas/graph/ — do not hand-edit. */
/* edges details for region "waves", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("waves.edges",{"edges":{
"blackbody-radiation:photoelectric-effect":{"type":"connection","label":{"zh":"两处都出现能量量子","en":"Energy quanta appear in both"},"reason":{"zh":"黑体辐射里 hν 的能量份解决了紫外发散，光电效应里同样的 hν 解释了光电子的最大动能，二者互相印证量子化。","en":"The energy unit hν resolves the ultraviolet divergence in blackbody radiation, and the same hν explains the maximum photoelectron energy, so the two support each other."},"source":"../physics/modern/blackbody-radiation/#step5"},
"carnot-cycle:work-energy":{"type":"connection","label":{"zh":"Q_h = W + Q_c 的能量账","en":"The energy ledger Q_h = W + Q_c"},"reason":{"zh":"一圈回来内能不变，吸的热一部分变成功、其余排给冷源，是能量守恒在热机上的账本。","en":"After one full cycle the internal energy is unchanged, so the heat taken in becomes work or is rejected to the cold sink, energy conservation applied to a heat engine."},"source":"../physics/thermal/carnot-cycle/#step3"},
"complex:fourier":{"type":"representation","label":{"zh":"表示旋转分量","en":"represents rotating components"},"reason":{"zh":"欧拉公式把正弦和余弦写成复指数的组合，复数傅里叶变换由此统一表示正、负频率分量。","en":"Euler’s formula expresses sine and cosine as combinations of complex exponentials, allowing the complex Fourier transform to represent positive and negative frequencies together."},"source":"https://www.dspguide.com/CH31.PDF#page=3"},
"conic-sections:net-force":{"type":"application","label":{"zh":"轨道是圆锥曲线","en":"Orbits are conics"},"reason":{"zh":"平方反比引力下，物体的轨道是以引力中心为焦点的圆锥曲线，离心率 e 决定它是椭圆、抛物线还是双曲线。","en":"Under an inverse-square force a body’s orbit is a conic with the attracting centre at a focus, and the eccentricity e decides whether it is an ellipse, parabola or hyperbola."},"source":"../math/geometry/conic-sections/#step1"},
"derivative:newton-laws":{"type":"application","label":{"zh":"加速度是速度的变化率","en":"Acceleration is the rate of change of velocity"},"reason":{"zh":"第 0 步把加速度当作速度每秒的变化量，频闪图里相邻残影的间距增加量就是它的直观样子。","en":"Step 0 treats acceleration as the change of velocity per second, and the growth of the gaps between ghosts is its visual form."},"source":"../physics/mechanics/newton-laws/#step0"},
"derivative:oscillation":{"type":"representation","label":{"zh":"描述运动的变化率","en":"describes motion rates"},"reason":{"zh":"本振子的可微位置 x(t) 给出 v=dx/dt、a=dv/dt；有方向的速度可以为负，速率是 |v|。微分描述运动，不是产生运动的物理原因。","en":"For this oscillator, v=dx/dt and a=dv/dt. Signed velocity can be negative; speed is |v|. Differentiation describes motion rather than causing it."},"source":"../math/calculus/derivative/#step0"},
"doppler-effect:fourier":{"type":"connection","label":{"zh":"频率是波的基本属性","en":"Frequency is a basic property of a wave"},"reason":{"zh":"要测出多普勒频移，得先读出信号里含哪些频率——傅里叶正是把任意信号拆成频率的工具，掠过时的频率曲线就是它读出来的。","en":"To measure a Doppler shift you must first read which frequencies a signal contains — Fourier analysis is the tool that splits any signal into frequencies, and the pass-by frequency curve is what it reads out."},"source":"../physics/waves/doppler-effect/#step1"},
"doppler-effect:spectrum":{"type":"application","label":{"zh":"掠过时频率随时间变","en":"Frequency changes with time in a pass-by"},"reason":{"zh":"掠过音调是频率随时间变的曲线——要同时看清“何时、何频”，就得用频谱/时频把它展开读，时间轴和频率轴一次给全。","en":"A pass-by pitch curve is a frequency changing with time — to see both 'when and what frequency' at once, you must unfold it with spectra or time–frequency reading, giving the time axis and the frequency axis together."},"source":"../physics/waves/doppler-effect/#step3"},
"double-slit:superposition":{"type":"connection","label":{"zh":"概率幅相加","en":"Amplitudes add"},"reason":{"zh":"单个粒子也走出干涉条纹，说明两条路径的“振幅”先相加再取平方；一旦路径可区分，就改为概率相加，条纹消失。","en":"Single particles still build interference fringes, which shows that the amplitudes of two paths add before squaring; once the paths are distinguishable, probabilities add instead and the fringes vanish."},"source":"../physics/modern/double-slit/#step3"},
"electric-fields:work-energy":{"type":"connection","label":{"zh":"势能与动能互换","en":"Potential and kinetic energy trade"},"reason":{"zh":"试探电荷运动中动能加势能保持不变，与功能关系同一账本。","en":"A test charge's kinetic plus potential energy stays constant, the same ledger as the work–energy relation."},"source":"../physics/electromagnetism/electric-fields/#step4"},
"electromagnetic-induction:oscillation":{"type":"connection","label":{"zh":"转动线圈给出正弦","en":"A spinning coil gives a sine"},"reason":{"zh":"匀速转动使磁通量按余弦变化，感应电动势是同频率的正弦波。","en":"Uniform rotation makes the flux a cosine, so the emf is a sine at the same frequency."},"source":"../physics/electromagnetism/electromagnetic-induction/#step4"},
"float-sink:net-force":{"type":"application","label":{"zh":"浮沉由合力方向决定","en":"Floating is decided by the net force"},"reason":{"zh":"重力向下、浮力向上，二者之差是合力：合力为零时物体在该位置保持静止（浮着），不为零就上浮或下沉。","en":"Weight pulls down and buoyancy pushes up; their difference is the net force: zero means the object rests (floats) there, otherwise it rises or sinks."},"source":"../physics/matter/float-sink/#step1"},
"fourier:convolution":{"type":"connection","label":{"zh":"把卷积变为乘法","en":"turns convolution into multiplication"},"reason":{"zh":"当相应变换存在时，时域卷积对应频域乘法。本课用有限序列比较直接卷积与频域计算的结果。","en":"When the transforms exist, time-domain convolution corresponds to frequency-domain multiplication. This lesson compares direct convolution with frequency-domain computation on finite sequences."},"source":"../signal/systems/convolution/#step6"},
"fourier:spectrum":{"type":"representation","label":{"zh":"给出频率表示","en":"produces a frequency representation"},"reason":{"zh":"变换结果包含各频率分量的信息；查看幅度与相位，才能保留一般信号的完整表示。","en":"The transform records frequency components; both amplitude and phase are needed for a complete representation of a general signal."},"source":"../signal/transforms/fourier/#step5"},
"fourier:wavelets":{"type":"representation","label":{"zh":"加入时间定位","en":"adds time localisation"},"reason":{"zh":"幅度谱对时间倒放不变，所以无法给出先后；对信号加窗或使用伸缩的小波后，才能同时看到频率和它出现的时刻。","en":"The magnitude spectrum is unchanged by time reversal, so it cannot give order; windowing the signal or using a scaled wavelet shows frequency together with when it occurs."},"source":"../signal/transforms/wavelets/#step0"},
"gravitational-lensing:work-energy":{"type":"connection","label":{"zh":"引力势决定偏折","en":"The gravitational potential sets the deflection"},"reason":{"zh":"偏折角正比于质量除以最近距离，也就是光线经过处的引力势大小，与引力势能随 1/r 变化的规律一致。","en":"The deflection angle is proportional to mass over closest distance, that is, to the gravitational potential where the ray passes, consistent with the 1/r dependence of gravitational potential energy."},"source":"../earth/astronomy/gravitational-lensing/#step0"},
"integral:oscillation":{"type":"application","label":{"zh":"累加往返的位移","en":"accumulates signed travel"},"reason":{"zh":"本振子往返一周回到同一位置，正负速度贡献抵消，位移为零；路程为4A。交换积分限使有向积分变号，按时间先后的路程仍非负。","en":"One oscillator cycle returns to the same position: opposite velocity contributions cancel, giving zero displacement but distance4A. Reversing limits changes an oriented integral’s sign; chronological path length remains nonnegative."},"source":"https://openstax.org/books/calculus-volume-1/pages/5-2-the-definite-integral"},
"integral:work-energy":{"type":"application","label":{"zh":"对位移累加力的作用","en":"integrates force over displacement"},"reason":{"zh":"一维功沿路径积 F dx，单位 N·m=J；a、b 可选时间端点，但积分变量 x 是位移，不是时间。弹簧往返时各段可做正功或负功。","en":"One-dimensional work integrates F dx along the path, in N·m=J. Time bounds a,b choose endpoint positions, but the integration variable x is displacement, not time. Spring work can be positive or negative along different legs."},"source":"https://openstax.org/books/university-physics-volume-1/pages/7-1-work"},
"interference:double-slit":{"type":"application","label":{"zh":"路程差决定明暗","en":"Path difference decides bright and dark"},"reason":{"zh":"两条缝到屏上一点的路程差等于波长整数倍时加强、半整数倍时抵消，这是干涉的路程差规则在双缝上的应用。","en":"The path difference from two slits to a screen point being a whole number of wavelengths reinforces and half-integers cancel, the path-difference rule of interference applied to a double slit."},"source":"../physics/modern/double-slit/#step0"},
"interference:superposition":{"type":"foundation","label":{"zh":"干涉是叠加算出来的","en":"Interference is computed by superposition"},"reason":{"zh":"两列波的概率幅先按叠加相加，再平方成概率；相长处明、相消处暗，条纹就是叠加的账本。","en":"Two waves' probability amplitudes first add by superposition, then square into probabilities; reinforcing places turn bright, cancelling places dark — fringes are superposition's ledger."},"source":"../physics/modern/double-slit/#step3"},
"kinetic-theory:blackbody-radiation":{"type":"foundation","label":{"zh":"温度是热能尺度 kT","en":"Temperature sets the thermal scale kT"},"reason":{"zh":"黑体辐射把一份光量子能量与热能 kT 比较，kT 正是气体动理论里温度对应的微观能量尺度。","en":"Blackbody radiation compares one light quantum with the thermal energy kT, the same microscopic energy scale that temperature has in kinetic theory."},"source":"../physics/modern/blackbody-radiation/#step5"},
"laplace:fourier":{"type":"connection","label":{"zh":"在收敛条件下限制到虚轴","en":"restricts to the imaginary axis when convergent"},"reason":{"zh":"当拉普拉斯变换的收敛域包含虚轴时，在 s = iω 处取值可得到傅里叶变换。","en":"If the Laplace region of convergence contains the imaginary axis, evaluating at s = iω gives the Fourier transform."},"source":"../signal/transforms/laplace/#step2"},
"lti:superposition":{"type":"connection","label":{"zh":"满足叠加性","en":"obeys superposition"},"reason":{"zh":"线性保证输入的加权组合产生相同权重的输出组合；时不变是另一项独立条件。","en":"Linearity preserves weighted combinations of input-output pairs; time invariance is a separate condition."},"source":"../signal/systems/lti-systems/#step3"},
"magnetic-force:oscillation":{"type":"connection","label":{"zh":"圆周运动的投影是振动","en":"A circle projects to an oscillation"},"reason":{"zh":"粒子绕圆匀速运动，其一个坐标随时间按正弦变化，周期与速度无关。","en":"Uniform motion on a circle makes each coordinate vary sinusoidally, with a period independent of speed."},"source":"../physics/electromagnetism/magnetic-force/#step2"},
"mechanical-energy:net-force":{"type":"connection","label":{"zh":"同一结果可以从力和能量两条路得到","en":"The same result by forces or by energy"},"reason":{"zh":"用牛顿第二定律沿轨道积分和用能量守恒得到同一个速度 √(2g(h₀ − h))，能量法不必知道轨道的形状。","en":"Integrating Newton’s second law along the track and using energy conservation give the same speed √(2g(h₀ − h)); the energy method does not need the shape of the track."},"source":"../physics/mechanics/mechanical-energy/#step1"},
"momentum-collision:impulse":{"type":"representation","label":{"zh":"冲量就是动量改变多少","en":"Impulse is how much momentum changes"},"reason":{"zh":"力乘时间等于动量改变量：同样的动量要停住，时间越长平均力越小——冲量不是新量，是动量变化的另一种说法。","en":"Force times time equals the change in momentum: to stop the same momentum, more time means less average force — impulse is not a new quantity, it is the momentum change stated another way."},"source":"../physics/mechanics/momentum-collision/#step1"},
"momentum-collision:work-energy":{"type":"connection","label":{"zh":"两条账本同时对账，才分得清弹性与粘性","en":"Two ledgers reconciled together tell elastic from sticky"},"reason":{"zh":"弹性碰撞动量与动能都守恒，粘性碰撞只守恒动量、多余的动能变热散掉；只看一条账本，分不清这两种碰撞。","en":"Elastic collisions conserve both momentum and kinetic energy; sticky ones conserve momentum only and lose the rest as heat. One ledger alone cannot tell the two apart."},"source":"../physics/mechanics/momentum-collision/#step2"},
"montecarlo:kinetic-theory":{"type":"connection","label":{"zh":"统计涨落随样本变小","en":"Fluctuations shrink with sample size"},"reason":{"zh":"压强读数的涨落随撞墙次数增多而变小，与蒙特卡洛的 1/√n 同类。","en":"Pressure readings fluctuate less as wall hits accumulate, the same 1/√n behaviour as Monte Carlo estimates."},"source":"../physics/thermal/kinetic-theory/#step0"},
"net-force:buoyancy-archimedes":{"type":"application","label":{"zh":"浮着即受力平衡","en":"Floating is a force balance"},"reason":{"zh":"物体静止浮在水面时，向上的浮力恰好等于向下的重力，净力为零；浮沉就是比较这两个力。","en":"A floating object at rest has upward buoyancy exactly equal to downward weight, so the net force is zero; float or sink is a comparison of these two forces."},"source":"../physics/matter/buoyancy-archimedes/#step3"},
"net-force:gravity-orbits":{"type":"application","label":{"zh":"平方反比的合力决定运动","en":"An inverse-square force decides the motion"},"reason":{"zh":"牛顿第二定律把 F = GMm/r² 变成加速度 g(r)，再用逐步积分得到轨道；轨道类型只取决于初速度。","en":"Newton’s second law turns F = GMm/r² into the acceleration g(r), and step-by-step integration gives the orbit; the type of orbit depends only on the launch speed."},"source":"../earth/astronomy/gravity-orbits/#step1"},
"net-force:momentum-collision":{"type":"foundation","label":{"zh":"碰撞是力在极短时间里改动量","en":"A collision is force changing momentum in a brief moment"},"reason":{"zh":"速度变了，变的正是动量；净力是动量变化的原因，碰撞把这个变化压缩进一瞬间，动量账本就是牛顿第二定律的账本。","en":"When velocity changes, what changes is momentum; net force is the cause of that change, and a collision squeezes it into a brief moment — the momentum ledger is Newton's second law kept as accounts."},"source":"../physics/mechanics/momentum-collision/#step0"},
"net-force:projectile-circular":{"type":"application","label":{"zh":"圆周需要向心的合力","en":"A circle needs an inward net force"},"reason":{"zh":"第 3 步把匀速圆周的向心加速度 v²/r 与指向圆心的合力对应，剪断绳子后物体沿切线飞出。","en":"Step 3 ties the centripetal acceleration v²/r to a net force toward the centre; cut the string and the body leaves along the tangent."},"source":"../physics/mechanics/projectile-circular/#step3"},
"net-force:relativity":{"type":"connection","label":{"zh":"低速时回到 F = ma","en":"At low speed it reduces to F = ma"},"reason":{"zh":"第 5 步显示相对论动能在 β 很小时与经典 ½mv² 几乎相同，牛顿力学是它的低速极限。","en":"Step 5 shows relativistic kinetic energy matches classical ½mv² at small β, so Newtonian mechanics is its low-speed limit."},"source":"../physics/modern/relativity/#step5"},
"net-force:vectors":{"type":"application","label":{"zh":"力的平衡是向量和为零","en":"Force balance is a vector sum of zero"},"reason":{"zh":"第 4 步把三个力画成首尾相接的闭合三角形，T₁ + T₂ + W = 0。","en":"Step 4 draws three forces as a closed head-to-tail triangle, T₁ + T₂ + W = 0."},"source":"../math/linear-algebra/vectors/#step4"},
"net-force:work-energy":{"type":"application","label":{"zh":"把净功联系到动能变化","en":"connects net work with kinetic change"},"reason":{"zh":"本例重力与支持力都不做功，弹簧力做功即物块净功。换系统或添加阻尼/驱动后，不能把单个力的功直接等同净功，也不能照搬本例机械能守恒。","en":"Here weight and support do zero work, so spring work is the block’s net work. In another system or with damping/driving, one force’s work is not generally net work, and this mechanical-energy conservation statement does not transfer automatically."},"source":"https://openstax.org/books/university-physics-volume-1/pages/7-3-work-energy-theorem"},
"newton-laws:net-force":{"type":"foundation","label":{"zh":"合力决定加速度","en":"Net force sets acceleration"},"reason":{"zh":"第 2 步让摩擦吃掉部分推力，只有剩下的合力才产生加速度，这正是 net-force 节点的核心。","en":"Step 2 lets friction eat part of the push so only the remaining net force accelerates the box, which is the core of the net-force node."},"source":"../physics/mechanics/newton-laws/#step2"},
"ohms-law:work-energy":{"type":"application","label":{"zh":"功率 P = UI","en":"Power P = VI"},"reason":{"zh":"第 3 步用同一条电阻看功率：保持电压或保持电流不变，随电阻变化的方向相反。","en":"Step 3 uses the same resistor to study power: holding voltage or holding current fixed gives opposite trends as R changes."},"source":"../physics/circuits/ohms-law/#step3"},
"oscillation:chaos-threebody":{"type":"connection","label":{"zh":"非线性系统的另一面","en":"The other side of nonlinear systems"},"reason":{"zh":"线性振动的行为规则可预测；加上非线性后，同样用微分方程描述的系统可以出现对初值极度敏感的混沌。","en":"Linear oscillation is regular and predictable; add nonlinearity and systems described by the same kind of differential equations can become chaotic, extremely sensitive to the starting point."},"source":"../physics/mechanics/chaos-threebody/#step2"},
"oscillation:net-force":{"type":"application","label":{"zh":"用净力决定加速度","en":"links net force to acceleration"},"reason":{"zh":"本水平无摩擦弹簧模型中，竖直重力与支持力抵消，水平合外力为 −kx=ma。不能把单个弹簧力在其他系统中也当作净力。","en":"In this horizontal frictionless spring model, weight and support cancel vertically; horizontal net force is −kx=ma. A single spring force is not generally the net force in other systems."},"source":"https://openstax.org/books/university-physics-volume-1/pages/5-3-newtons-second-law"},
"oscillation:resonance":{"type":"application","label":{"zh":"给振动加上阻尼和推力","en":"Add damping and a push to an oscillation"},"reason":{"zh":"自由振动加上阻尼与周期推力，就得到稳态振幅随频率变化的共振曲线。","en":"Adding damping and a periodic push to free oscillation gives a steady-state amplitude that varies with frequency: the resonance curve."},"source":"../physics/waves/resonance/#step2"},
"particles-states:kinetic-theory":{"type":"foundation","label":{"zh":"温度就是粒子闹腾程度的标尺","en":"Temperature gauges how wildly particles move"},"reason":{"zh":"本页温度滑杆直接调粒子抖动的剧烈程度，温度读数与粒子平均动能同源——这正是分子动理论的定性口径：越热，粒子平均动得越凶。","en":"This page's temperature slider directly sets how violently particles vibrate, and its reading shares its source with average particle kinetic energy — the qualitative statement of kinetic theory: hotter means wilder on average."},"source":"../chemistry/matter/particles-states/#step1"},
"photoelectric-effect:interference":{"type":"connection","label":{"zh":"光的粒子面与波动面","en":"The particle side and wave side of light"},"reason":{"zh":"干涉证明光有波动性，光电效应显示能量一份一份交付，两者互补。","en":"Interference shows light is a wave, while the photoelectric effect shows its energy delivered in packets; the two are complementary."},"source":"../physics/modern/photoelectric-effect/#step4"},
"photoelectric-effect:spectrum":{"type":"connection","label":{"zh":"频率决定光子能量","en":"Frequency sets photon energy"},"reason":{"zh":"光谱按频率排列，光电效应里每个频率对应一份确定的光子能量 hf。","en":"A spectrum orders light by frequency, and in the photoelectric effect each frequency corresponds to a definite photon energy hf."},"source":"../physics/modern/photoelectric-effect/#step1"},
"pinhole-ratio:eye-vision":{"type":"connection","label":{"zh":"小瞳孔像小孔一样增加景深","en":"A small pupil acts like a pinhole and deepens the field"},"reason":{"zh":"同样的失焦，孔径越小模糊斑越小：瞳孔缩小就像小孔成像一样，让更大范围的物距都显得清晰。","en":"For the same defocus a smaller aperture gives a smaller blur spot; a constricted pupil acts like a pinhole and keeps a wider range of distances looking sharp."},"source":"../physics/optics/eye-vision/#step4"},
"pressure:work-energy":{"type":"connection","label":{"zh":"力放大、位移缩小","en":"Force gain, shorter travel"},"reason":{"zh":"液压机里 F₂ = F₁·S₂/S₁ 放大了力，但大活塞位移按同一比例缩小，理想情况下输入功等于输出功，这正是功与能量的账本。","en":"In a hydraulic press F₂ = F₁·S₂/S₁ multiplies force while the big piston’s travel shrinks by the same factor, so ideal input work equals output work — the work–energy ledger."},"source":"../physics/matter/pressure/#step4"},
"probability:kinetic-theory":{"type":"connection","label":{"zh":"速率分布来自随机碰撞","en":"Random collisions shape the speed distribution"},"reason":{"zh":"大量粒子的随机碰撞让速率分布趋向固定形状，个别粒子不可预测。","en":"Random collisions among many particles drive the speed distribution to a fixed shape while single particles stay unpredictable."},"source":"../physics/thermal/kinetic-theory/#step3"},
"quantum-tunneling:interference":{"type":"connection","label":{"zh":"入射波与反射波叠加成波纹","en":"Incoming plus reflected waves make ripples"},"reason":{"zh":"第 0 步墙前的 |ψ|² 波纹，是入射波与反射波的干涉；与干涉页的叠加原理相同。","en":"The ripples of |ψ|² before the wall in step 0 are interference of the incoming and reflected waves, the same superposition as on the interference page."},"source":"../physics/modern/quantum-tunneling/#step0"},
"quantum-tunneling:sampling":{"type":"connection","label":{"zh":"数值解波动方程需要网格","en":"Solving a wave equation numerically needs a grid"},"reason":{"zh":"第 3 步把连续的波用 360 个网格点表示并按固定步长推进，网格与步长的选择与采样页讲的离散化同类。","en":"Step 3 represents the continuous wave on 360 grid points advanced with a fixed step; choosing grid and step is the same kind of discretisation the sampling page discusses."},"source":"../physics/modern/quantum-tunneling/#step3"},
"relativity:spectrum":{"type":"connection","label":{"zh":"光速在所有参考系相同","en":"Light speed is the same in every frame"},"reason":{"zh":"第 4 步速度合成中 w = 1（光）对任何 v 结果都是 1，说明电磁波在所有观察者那里速度相同，与光谱页的波速概念一致。","en":"In step 4, w = 1 (light) gives u = 1 for any v, so electromagnetic waves travel at the same speed for every observer, consistent with the wave speed in the spectrum page."},"source":"../physics/modern/relativity/#step4"},
"resonance:freqresp":{"type":"representation","label":{"zh":"表现为响应峰值","en":"appears as a response peak"},"reason":{"zh":"在线性系统的频率响应幅度图上，共振表现为某段频率附近的峰；并非所有系统都有明显峰值。","en":"In a linear system’s frequency-response magnitude, resonance appears as a peak; not every system has a pronounced one."},"source":"../signal/systems/frequency-response/#step5"},
"resonance:resonance":{"type":"connection","label":{"zh":"同一现象的力学版","en":"The mechanical version of the same effect"},"reason":{"zh":"质量—弹簧系统在特定驱动频率下振幅陡增、偏离频率振幅骤降——这正是“频率选择性”的实物演示：共振不是什么频率都响应，只挑中自己的频率。","en":"A mass–spring system surges in amplitude at one driving frequency and drops off away from it — that is frequency selectivity in physical form: resonance does not respond to every frequency, only to its own."},"source":"../physics/waves/resonance/#step3"},
"seismic-waves:superposition":{"type":"connection","label":{"zh":"地震图是多种波的叠加","en":"A seismogram is a sum of several waves"},"reason":{"zh":"第 0 步的地震图由背景噪声、P 波与 S 波叠加而成，读图就是识别叠加中各个到达时刻。","en":"Step 0’s seismogram is background noise plus a P wave plus an S wave, and reading it means picking out each arrival in the sum."},"source":"../earth/geo/seismic-waves/#step0"},
"similarity-scaling:pinhole-ratio":{"type":"connection","label":{"zh":"同样是相似三角形","en":"The same similar triangles"},"reason":{"zh":"小孔成像里物与像的比例、影子测高里杆与树的比例，都来自一对相似三角形的对应边成比例。","en":"The object-to-image ratio in a pinhole camera and the stick-to-tree ratio in shadow measuring both come from corresponding sides of similar triangles."},"source":"../math/geometry/similarity-scaling/#step3"},
"sine:fourier":{"type":"foundation","label":{"zh":"提供频率分量","en":"provides frequency components"},"reason":{"zh":"傅里叶分析以不同频率的正弦、余弦或复指数为分量；每个分量有自己的幅度和相位。","en":"Fourier analysis uses sine, cosine or complex-exponential components at different frequencies, with their own amplitudes and phases."},"source":"../signal/transforms/fourier/#step1"},
"sine:interference":{"type":"application","label":{"zh":"用相位差确定合振幅","en":"uses relative phase to determine resultant amplitude"},"reason":{"zh":"同一点的两列线性简谐波逐时相加；同频等振幅且相对相位固定时，B=2A|cos(δ/2)|。这是一条应用连接，不表示必须先学完另一课程。","en":"Two linear sinusoids add at the same point and time. For fixed relative phase, equal frequency and equal received amplitude, B=2A|cos(δ/2)|. This is an application, not a required course order."},"source":"../physics/waves/interference/#step3"},
"sine:oscillation":{"type":"representation","label":{"zh":"描述理想运动","en":"describes ideal motion"},"reason":{"zh":"无阻尼、无持续外力驱动（回复力仍存在）的理想弹簧振子满足 x″ + (k/m)x = 0，其解为正弦和余弦的组合。","en":"An ideal spring without damping or sustained driving, with its restoring force still present, obeys x″ + (k/m)x = 0, whose solutions combine sine and cosine."},"source":"https://openstax.org/books/university-physics-volume-1/pages/15-1-simple-harmonic-motion","reading":{"title":{"zh":"这是一种表示方式，不是必修箭头","en":"A representation, not a mandatory learning order"},"meaning":{"zh":"正弦／余弦函数描述理想弹簧的位移怎样变化，并不产生运动。圆周投影是看懂这个函数的辅助图像；弹簧块实际沿直线往返，不沿圆周运动。","en":"Sine and cosine describe how an ideal spring’s position changes; they do not cause the motion. Circular projection helps visualize that function. The spring mass travels along a line, not around the circle."},"startNode":"sine","startHint":{"zh":"如果振幅、频率或相位还陌生，可先看正弦与余弦；已经熟悉就直接试投影实验，不必按箭头重新学一遍。","en":"If amplitude, frequency or phase are unfamiliar, revisit sine and cosine first. If familiar, try the projection experiment directly; the arrow does not require repeating a course."},"trail":"motion","tryNode":"oscillation","bounds":{"zh":"这里限定 m、k 为正的理想线性弹簧，无阻尼、无持续驱动，回复力仍然存在。圆点匀速转动，不代表它的投影匀速往返；其他往返运动不一定符合这套模型。","en":"This comparison uses a positive-mass, positive-stiffness ideal linear spring without damping or sustained driving; its restoring force remains. Constant-speed rotation does not make the projection’s velocity constant. Other oscillations need not fit this model."},"source":"https://openstax.org/books/university-physics-volume-1/pages/15-3-comparing-simple-harmonic-motion-and-circular-motion"}},
"slope:pinhole-ratio":{"type":"application","label":{"zh":"用同一直线得到相似比","en":"uses one straight line to obtain the ratio"},"reason":{"zh":"以孔心为原点，同一条非竖直光线保持斜率；孔两侧三角形相似，坐标反号给出带符号放大率M=−v/u。光线斜率与放大率不是同一个量，这个关系不是透镜焦距公式。","en":"With the hole as origin, a nonvertical ray keeps one slope. Similar triangles on opposite sides reverse the coordinate sign, giving signed magnification M=−v/u. Ray slope and magnification are different quantities; this is not a lens focal-length formula."},"source":"../physics/optics/pinhole-camera/#geometry-bridge"},
"snell:eye-vision":{"type":"application","label":{"zh":"折射让晶状体会聚光线","en":"Refraction lets the lens converge light"},"reason":{"zh":"晶状体的会聚作用来自光在曲面界面上的折射；曲率越大屈光力越强，这就是调节的物理基础。","en":"The lens converges light by refraction at curved interfaces; more curvature means more power, which is the physical basis of accommodation."},"source":"../physics/optics/eye-vision/#step1"},
"snell:gravitational-lensing":{"type":"application","label":{"zh":"光路被“介质”弯折","en":"The light path bent by a “medium”"},"reason":{"zh":"引力场相当于折射率随位置变化的介质，光线向质量偏折，与光在界面上折射的几何很像，只是原因是时空弯曲。","en":"A gravitational field acts like a medium whose refractive index varies with position, bending rays toward the mass, geometrically similar to refraction at an interface but caused by curved spacetime."},"source":"../earth/astronomy/gravitational-lensing/#step1"},
"snell:seismic-waves":{"type":"application","label":{"zh":"波线在速度变化处折射","en":"Rays refract where speed changes"},"reason":{"zh":"第 2 步用球层中守恒的射线参数 p = r sinθ/v（折射定律的球对称形式）追踪地震波线。","en":"Step 2 traces seismic rays with the ray parameter p = r sinθ/v conserved in a sphere, the spherical form of Snell’s law."},"source":"../earth/geo/seismic-waves/#step2"},
"sound-vibration:oscillation":{"type":"application","label":{"zh":"鼓面是一个振动","en":"A drumhead is an oscillation"},"reason":{"zh":"鼓面来回运动并逐渐衰减，可以用振幅、频率描述，这正是振动（振子）的基本量。","en":"The drumhead moves back and forth and gradually dies away; amplitude and frequency describe it, the basic quantities of an oscillation."},"source":"../physics/waves/sound-vibration/#step0"},
"sound-waves:fourier":{"type":"connection","label":{"zh":"音色就是谐波的叠加","en":"Timbre is a sum of harmonics"},"reason":{"zh":"第 3 步用 n 倍频的正弦波按不同强度叠加得到各种波形，是傅里叶“任何周期波形都是正弦之和”的直观例子。","en":"Step 3 builds waveforms from sine waves at multiples of one frequency with different strengths, a hands-on case of Fourier’s “any periodic wave is a sum of sines”."},"source":"../physics/waves/sound-waves/#step3"},
"spectrum:sampling":{"type":"foundation","label":{"zh":"解释频谱重叠","en":"explains spectral overlap"},"reason":{"zh":"均匀采样使频谱按采样率周期重复；重复的谱相互重叠时产生混叠。","en":"Uniform sampling repeats the spectrum at multiples of the sampling rate; overlap between copies produces aliasing."},"source":"../signal/sampling/sampling/#step4"},
"spectrum:wavelets":{"type":"connection","label":{"zh":"谱图是加窗的频谱","en":"a spectrogram is a windowed spectrum"},"reason":{"zh":"谱图把一串滑动窗口的频谱按时间排成图；窗口越长频率越准、时间越糊。","en":"A spectrogram stacks the spectra of a sliding window over time; a longer window gives sharper frequency but blurrier time."},"source":"../signal/transforms/wavelets/#step1"},
"superposition:doppler-effect":{"type":"connection","label":{"zh":"波前叠加成不等间距","en":"Wavefronts form unequal spacing"},"reason":{"zh":"运动源每个波前的圆心不同，叠起来前密后疏，间距决定听到的频率。","en":"Each wavefront of a moving source has a different centre, so the set is dense ahead and sparse behind, and the spacing sets the heard frequency."},"source":"../physics/waves/doppler-effect/#step1"},
"superposition:electric-fields":{"type":"application","label":{"zh":"场的叠加","en":"Fields superpose"},"reason":{"zh":"多个电荷的电场逐点矢量相加，是叠加原理的一个具体例子。","en":"The fields of several charges add as vectors point by point, a concrete case of the superposition principle."},"source":"../physics/electromagnetism/electric-fields/#step1"},
"superposition:fourier":{"type":"foundation","label":{"zh":"把分量合成信号","en":"combines components into signals"},"reason":{"zh":"傅里叶级数通过叠加谐波近似周期波形；有限项近似在跳变附近可能出现吉布斯现象。","en":"A Fourier series combines harmonics to approximate a periodic waveform; finite sums may show Gibbs overshoot near jumps."},"source":"../signal/transforms/fourier/#step4"},
"superposition:sound-waves":{"type":"application","label":{"zh":"拍是两列波的叠加","en":"Beats are two waves superposed"},"reason":{"zh":"第 2 步把两个相近频率的声波相加，得到按 |f₁−f₂| 起伏的包络，是叠加原理的直接应用。","en":"Step 2 adds two sound waves of close frequency and gets an envelope swelling at |f₁−f₂|, a direct use of superposition."},"source":"../physics/waves/sound-waves/#step2"},
"taylor-series:fourier":{"type":"connection","label":{"zh":"局部逼近 vs 整体逼近","en":"Local vs global approximation"},"reason":{"zh":"第 5 步对同一函数并排展示泰勒（一点的高阶导数）与傅里叶（整段区间的积分）两种逼近，收敛行为不同。","en":"Step 5 shows Taylor (higher derivatives at a point) and Fourier (integrals over a stretch) side by side on one function, with different convergence behaviour."},"source":"../math/calculus/taylor-series/#step5"},
"unit-circle:snell":{"type":"application","label":{"zh":"正弦范围判断折射解","en":"sine range tests refraction solutions"},"reason":{"zh":"单位圆给出sin的值域；Snell关系要求sinθ₂=(n₁/n₂)sinθ₁，右侧超过1时没有传播折射光线。光学角从法线起，而不是单位圆默认的水平轴。","en":"The unit circle supplies sine’s range. Snell requires sinθ₂=(n₁/n₂)sinθ₁; above1, no propagating refracted ray exists. Optical angles start at the normal, rather than the unit circle’s usual horizontal axis."},"source":"../physics/optics/reflection-refraction/#critical-proof"},
"velocity-vt:projectile-circular":{"type":"application","label":{"zh":"匀速加分量地看运动","en":"Treating motion one component at a time"},"reason":{"zh":"第 0 步把水平匀速与竖直匀加速分开处理，是速度—时间图中位移公式的二维应用。","en":"Step 0 treats horizontal uniform motion and vertical uniform acceleration separately, a two-dimensional use of the displacement ideas from velocity–time graphs."},"source":"../physics/mechanics/projectile-circular/#step0"},
"work-energy:carnot-cycle":{"type":"application","label":{"zh":"功是 p–V 曲线下面积","en":"Work as area under p–V"},"reason":{"zh":"气体对外做功 W = ∫P dV，是功—能量关系在气体上的具体形式；一圈的净功等于回路围出的面积。","en":"The work done by a gas, W = ∫P dV, is the work–energy relation for a gas; the net work of a cycle equals the area enclosed by the loop."},"source":"../physics/thermal/carnot-cycle/#step0"},
"work-energy:energy-pyramid":{"type":"application","label":{"zh":"能量只会被消耗，不会凭空增加","en":"Energy is spent, never created"},"reason":{"zh":"每传一级一部分变成热散失，能量金字塔上小下大是能量守恒与耗散的结果。","en":"A share is lost as heat at each step, so the energy pyramid narrows upward as a result of conservation with dissipation."},"source":"../biology/ecology/energy-pyramid/#step1"},
"work-energy:gravity-orbits":{"type":"connection","label":{"zh":"能量守恒给出逃逸速度","en":"Energy conservation gives the escape speed"},"reason":{"zh":"动能加引力势能 −GMm/r 守恒；总能量为 0 时恰好逃逸，由此得到逃逸速度 √(2GM/r)。","en":"Kinetic plus gravitational potential energy −GMm/r is conserved; a total energy of zero is the threshold of escape, which gives the escape speed √(2GM/r)."},"source":"../earth/astronomy/gravity-orbits/#step2"},
"work-energy:kinetic-theory":{"type":"application","label":{"zh":"动能的统计平均","en":"Averaging kinetic energy"},"reason":{"zh":"温度被读作粒子平均动能，压强由撞墙冲量算出。","en":"Temperature is read as mean kinetic energy and pressure comes from wall impulses."},"source":"../physics/thermal/kinetic-theory/#step1"},
"work-energy:mechanical-energy":{"type":"application","label":{"zh":"功改变能量，摩擦做的功变成热","en":"Work changes energy; friction’s work becomes heat"},"reason":{"zh":"外力或摩擦力做的功等于能量的变化；只有重力和弹力做功时机械能守恒，摩擦做功则把机械能转为内能。","en":"The work of outside forces or friction equals the change in energy; mechanical energy is conserved when only gravity and elastic forces do work, while friction turns it into internal energy."},"source":"../physics/mechanics/mechanical-energy/#step2"},
"work-energy:photoelectric-effect":{"type":"application","label":{"zh":"能量账本","en":"Energy ledger"},"reason":{"zh":"hf = φ + E_k 是功能关系用在一个光子和一个电子上。","en":"hf = φ + E_k is the work–energy bookkeeping applied to one photon and one electron."},"source":"../physics/modern/photoelectric-effect/#step1"}
}});
